export function identity(auth){if(!auth||!['owner','admin','reseller','manager','admin1'].includes(auth.role))throw error('AI_FORBIDDEN',403);if(auth.role==='owner')return 'owner:'+String(auth.id||'primary');if(!auth.id)throw error('AI_IDENTITY_MISSING',403);return auth.role+':'+String(auth.id);}
function value(k,otherwise){const row=store().prepare('SELECT v FROM settings WHERE k=?').get(k);return row?JSON.parse(row.v):otherwise;}
function set(k,v){store().prepare('INSERT INTO settings VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v').run(k,JSON.stringify(v));}
