LPN, comma separated'],certFile:['مسیر گواهی روی سرور مقصد','Certificate path on destination'],keyFile:['مسیر کلید TLS روی سرور مقصد','TLS key path on destination'],dest:['مقصد Reality: host:port','Reality destination: host:port'],privateKey:['کلید خصوصی Reality','Reality private key'],publicKey:['کلید عمومی Reality','Reality public key'],shortIds:['Short IDs با ویرگول','Short IDs, comma separated'],ssPassword:['کلید Shadowsocks 2022','Shadowsocks 2022 key'],target:['مقصد انتقال پورت','Forward target'],targetPort:['پورت مقصد','Target port']};
  const defaults={kcpMtu:1350,kcpTti:30,kcpUplink:5,kcpDownlink:20,kcpReadBuffer:2,kcpWriteBuffer:2,kcpSeed:'',cipherSuites:'',maxTimeDiff:0,minClientVer:'',maxClientVer:'',sniffDomainsExcluded:'',sniffDestOverride:'http,tls,quic',tcpKeepAliveIdle:300,tcpKeepAliveInterval:30,tcpUserTimeout:0,tcpMaxSeg:0,mark:0,interface:'',initialWindowsSize:0,idleTimeout:60,healthCheckTimeout:20,maxEarlyData:0,earlyDataHeaderName:'Sec-WebSocket-Protocol',remark:'',port:8443,listen:'0.0.0.0',outbound:'',path:'/',host:'',serviceName:'',sni:'',alpn:'h2,http/1.1',certFile:'/etc/nova/origin.pem',keyFile:'/etc/nova/origin.key',dest:'',privateKey:'',publicKey:'',shortIds:'',ssPassword:'',target:'',targetPort:''};
