cat > "$APP/console.css" <<'ALIREZA_D60D84DD9A7F28A7D167D394'
/* Only AI and remote DNS documents load this sheet. Native panel and AdGuard do not. */
body{background:var(--bg);font-size:14px;line-height:1.8}main{max-width:1400px;padding:28px}header{padding:8px 0 22px;border-bottom:1px solid var(--line)}h1{font-size:28px;letter-spacing:-.5px}.card{border-radius:var(--az-r-lg,18px);background:var(--az-card,var(--panel));box-shadow:var(--az-shadow-card,0 12px 36px #0002)}button,.button,input,select,textarea{border-radius:var(--az-r-sm,10px)}button:focus-visible,.button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.chat-layout{gap:16px}.history{position:sticky;top:20px}.history>button{background:var(--az-grad,var(--accent))}.chat{background:linear-gradient(145deg,var(--az-card,var(--panel)),var(--az-surface-1,var(--panel)))}.message{box-shadow:var(--az-shadow-card,0 6px 20px #0001)}.message.user{border-color:color-mix(in srgb,var(--accent) 32%,var(--line));background:color-mix(in srgb,var(--accent) 7%,var(--panel))}.message.model{background:var(--az-surface-2,var(--panel))}.message .copy{opacity:.7}.message:hover .copy,.message:focus-within .copy{opacity:1}.composer{position:relative}.composer textarea{background:var(--az-input-bg,var(--bg));min-height:112px}.suggestions button{border-style:dashed;background:transparent}.eyebrow{font-size:10px;letter-spacing:2px}.steps{counter-reset:step;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:14px;overflow:hidden}.steps span{margin:0;border:0;border-radius:0;background:var(--panel);padding:16px;display:flex;gap:12px;align-items:center}.steps span:before{counter-increment:step;content:counter(step);display:grid;place-items:center;min-width:30px;height:30px;border:1px solid var(--line);border-radius:50%;font-variant-numeric:tabular-nums}.steps span.active{background:color-mix(in srgb,var(--accent) 6%,var(--panel))}.steps span.active:before{background:var(--az-grad,var(--accent));color:var(--az-ac-ink,#fff);border-color:transparent}.node-grid .card{transition:border-color .2s,box-shadow .2s}.node-grid .card:hover{border-color:var(--accent);box-shadow:var(--az-shadow-card-hover,0 12px 30px #0002)}#fingerprint{background:var(--az-input-bg,var(--bg));border-color:var(--accent)}#install>details{padding:16px;border:1px solid var(--line);border-radius:12px}#install summary{cursor:pointer;color:var(--text)}#install>details[open] summary{margin-bottom:14px}#jobs:empty{display:none}.job{background:var(--az-surface-2,var(--panel))}@media(max-width:750px){main{padding:16px 12px}.history{position:static}.chat{padding:14px}.steps span{min-width:100%;padding:12px}.composer .actions{gap:8px}.card{padding:18px}h1{font-size:24px}}
/* Sales, AI and destination installer studio. Loaded only by these documents. */
.studio{max-width:1480px;padding:32px clamp(16px,3.5vw,56px);margin:auto}.studio-hero{position:relative;isolation:isolate;display:flex;flex-wrap:wrap;gap:24px;padding:28px 30px;margin-bottom:28px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(125deg,color-mix(in srgb,var(--accent) 10%,var(--panel)),var(--panel) 65%);box-shadow:var(--az-shadow-card,0 12px 38px #0002)}.studio-hero>div{flex:1;min-width:190px}.studio-hero h1{font-size:clamp(26px,3vw,40px);letter-spacing:-1px;line-height:1.35}.studio-hero svg{width:48px;height:48px;color:var(--accent);flex:none;padding:10px;border:1px solid color-mix(in srgb,var(--accent) 28%,var(--line));border-radius:16px;background:color-mix(in srgb,var(--accent) 7%,var(--panel))}.studio-tabs{display:flex;flex-wrap:wrap;gap:8px;padding:8px;border:1px solid var(--line);border-radius:16px;margin-block:20px;background:var(--panel)}.studio-tabs button{flex:1;min-width:120px;border:0}.studio-panel{padding:28px}.studio-price{display:block;font-size:26px;letter-spacing:-.6px;color:var(--text);font-variant-numeric:tabular-nums}.studio-plan{padding:22px!important;box-shadow:none!important;margin:0!important}.studio-row,.az-store-row{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:18px 0;border-bottom:1px solid var(--line)}.studio-row>div{min-width:0;overflow-wrap:anywhere}.studio-row .mono{font-size:12px;color:var(--muted)}.studio-checks{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}fieldset{border:1px solid var(--line);border-radius:16px;padding:18px;min-width:0}legend{padding-inline:8px;color:var(--text);font-weight:650}.check{display:flex;align-items:center;gap:10px;color:var(--text);font-size:13px}.check input[type=checkbox],input[type=checkbox]{width:auto;flex:none;accent-color:var(--accent)}#planform{margin-top:18px}.ai-studio .chat-layout{grid-template-columns:260px minmax(0,1fr);min-height:calc(100dvh - 260px);align-items:start}.ai-studio .history{background:var(--panel);padding:18px;border-radius:20px;position:sticky;top:16px}.ai-studio .history h3{font-size:12px;color:var(--muted);margin:24px 0 12px}.ai-studio #history>div{display:flex;gap:5px;align-items:center;border-bottom:1px solid var(--line);padding-block:5px}.ai-studio #history button{margin:0;border:0;background:transparent;font-size:12px;padding:9px;min-width:0}.ai-studio #history>div button:first-child{flex:1;text-overflow:ellipsis;overflow:hidden;white-space:nowrap}.ai-studio #history>div button:last-child{width:auto;opacity:.65}.ai-studio .chat{padding:24px;min-height:600px;box-shadow:0 16px 48px #0001}.ai-studio #status{padding:5px 10px;border-radius:20px;border:1px solid var(--line);max-width:70%;line-height:1.5}.ai-welcome{padding:30px 12px 16px;text-align:center}.ai-welcome h2{font-size:26px;letter-spacing:-.7px;margin:12px 0}.ai-welcome .orb{display:grid;place-items:center;width:56px;height:56px;border:1px solid var(--line);border-radius:20px;margin:auto;color:var(--accent);font-size:28px;background:linear-gradient(140deg,color-mix(in srgb,var(--accent) 12%,var(--panel)),var(--panel));box-shadow:0 10px 30px color-mix(in srgb,var(--accent) 10%,transparent)}.ai-studio .suggestions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.ai-studio .suggestions button{font-size:12px;line-height:1.8;padding:14px;text-align:start;min-width:0;border-style:solid}.ai-studio .messages:empty{display:none}.ai-studio .message{position:relative;border-radius:16px;margin:16px 0;padding:18px 20px;box-shadow:none;font-size:14px}.ai-studio .message.model{border-inline-start:3px solid var(--accent)}.ai-studio .message.user{margin-inline-start:12%;background:color-mix(in srgb,var(--accent) 7%,var(--panel));border-color:color-mix(in srgb,var(--accent) 20%,var(--line))}.ai-studio .message .text{line-height:2}.ai-studio .composer{margin-top:auto;padding-top:20px}.ai-studio .composer textarea{border-radius:16px;min-height:100px;box-shadow:inset 0 2px 8px #0001}.ai-studio #send:before{content:'↑';display:inline-grid;place-items:center;width:20px;height:20px;border-radius:6px;margin-inline-end:8px;background:#ffffff20;font:700 18px system-ui}.ai-studio .composer>label{font-size:12px;margin-bottom:7px}.ai-studio .hint{font-size:11px}.dns-studio .card{margin-bottom:22px}.dns-studio #install .grid{gap:20px}.dns-studio #install label>span{display:block;font-size:12px;margin-bottom:8px}.dns-studio #nodes:empty{min-height:70px}.dns-studio .steps{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin:24px 0}.dns-studio .steps span{min-width:0;font-size:12px}.dns-studio #install>.actions{padding-top:22px;margin-top:22px;border-top:1px solid var(--line)}.dns-studio #install>.actions button{min-height:48px}.dns-studio #probe:before{content:'⌁';margin-inline-end:8px}.dns-studio #deploy:before{content:'↗';margin-inline-end:8px}html[lang=en] [lang=fa],html[lang=fa] [lang=en]{display:none!important}button:active:not(:disabled){transform:translateY(1px)}
@media(max-width:800px){.studio{padding:16px 12px}.studio-hero{padding:20px;gap:14px;border-radius:20px}.studio-hero svg{width:40px;height:40px;padding:8px}.studio-panel{padding:18px}.studio-row{align-items:start;flex-direction:column}.ai-studio .chat-layout{grid-template-columns:1fr}.ai-studio .history{position:static;max-height:190px;overflow:auto}.ai-studio .history h3{margin-top:12px}.ai-studio .chat{min-height:540px;padding:18px}.ai-studio .suggestions{grid-template-columns:1fr}.ai-studio .suggestions button{padding:10px 14px}.ai-welcome{padding:16px 8px}.ai-welcome h2{font-size:21px}.dns-studio .steps{grid-template-columns:1fr}.dns-studio #install>.actions button{width:100%}.studio-tabs{gap:5px}.studio-tabs button{min-width:42%;font-size:12px}}
