UI_FILES=['panels.php','function.php','panel/js/product-services.js','panels/Api/alireza_services.php','db/tables/product.php','panel/js/reseller.js','alireza-panel-account.php','cronbot/jobs.php','cronbot/alireza_shop_recovery.php','alireza-shop.php','index.php','keyboard.php','panel/reseller.php','panel/product.php','panel/js/product.js','api/product.php','panels/Api/x-ui_single.php','lang/fa.php','lang/en.php','lang/ru.php','lang/zh.php','panels/Api/alireza_local.php','panels/Drivers/XuiSingle.php','panel/inc/layout_head.php','panel/inc/layout_foot.php','panel/inc/alireza_appearance.php','panel/settings.php','panel/appearance.php','panel/js/app.js','panel/js/settings.js','panel/js/alireza-appearance.js','panel/js/sort_keyboard.js','panel/css/cyberpunk_theme.css','panel/css/alireza-appearance.css']
def upgrade_ui():
    if not (APP/'.alirezaserver-managed').exists():return {'installed':False}
    data=base64.b64decode((HERE/'alirezabot-source.tar.b64').read_bytes())
    manifest=json.loads((HERE/'reference-versions.json').read_text())
    if hashlib.sha256(data).hexdigest()!=manifest['bot']['packagedSHA256']:raise RuntimeError('BOT_PAYLOAD_CHECKSUM')
    import io
    backup=STATE/('ui-backup-'+time.strftime('%Y%m%dT%H%M%SZ')+'.tar.gz')
    changes=[]
    with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as tar:
        for name in UI_FILES:
            member=tar.getmember(name)
            if not member.isfile():raise RuntimeError('UNSAFE_BOT_ARCHIVE')
            path=APP/name
            for ancestor in [path,*path.parents]:
                if ancestor==APP.parent:break
                if ancestor.is_symlink():raise RuntimeError('BOT_SYMLINK_REFUSED')
            content=tar.extractfile(member).read()
            if not path.exists() or path.read_bytes()!=content:changes.append((path,content))
    if not changes:return {'changed':False}
    STATE.mkdir(parents=True,exist_ok=True,mode=0o750)
    with tarfile.open(backup,'w:gz') as old:
        for path,_ in changes:
            if path.exists():old.add(path,arcname=path.relative_to(APP).as_posix())
    backup.chmod(0o600)
    for path,content in changes:
        path.parent.mkdir(parents=True,exist_ok=True)
        temp=path.with_name(path.name+'.rc6-new');temp.write_bytes(content);temp.chmod(0o640);shutil.chown(temp,user='alirezabot',group='alirezabot');os.replace(temp,path)
    return {'changed':True,'backup':str(backup)}

def repair_web():
    if not (APP/'.alirezaserver-managed').exists():return {'installed':False}
    conf=APP/'php-fpm.conf'
    if conf.is_symlink():raise RuntimeError('BOT_CONFIG_SYMLINK_REFUSED')
    old=conf.read_text();new=old.replace('error_log=/proc/self/fd/2','error_log=syslog').replace('php_admin_value[error_log]=/proc/self/fd/2','php_admin_value[error_log]=syslog')
    if new!=old:
        backup=APP/'php-fpm.conf.before-rc6'
        if not backup.exists():backup.write_text(old);backup.chmod(0o600)
        conf.write_text(new);conf.chmod(0o640)
    run([str(php_fpm()),'--test','--fpm-config',str(conf)],timeout=15)
    if new!=old or subprocess.run(['systemctl','is-active','--quiet','alirezabot-php.service']).returncode:
        run(['systemctl','restart','alirezabot-php.service'],timeout=30)
    for _ in range(20):
        if pathlib.Path('/run/alirezabot/php.sock').is_socket() and subprocess.run(['systemctl','is-active','--quiet','alirezabot-php.service']).returncode==0:return {'installed':True,'webReady':True}
        time.sleep(.25)
    raise RuntimeError('BOT_PHP_NOT_READY_CHECK_JOURNAL')

def reset_password(v):
    if os.geteuid()!=0:raise RuntimeError('ROOT_REQUIRED')
    if not (APP/'.alirezaserver-managed').exists():raise RuntimeError('BOT_NOT_INSTALLED')
    password=v.get('password') or secrets.token_urlsafe(18)
    if not isinstance(password,str) or not 12<=len(password)<=128:raise RuntimeError('PASSWORD_LENGTH_12_TO_128')
    script="""require '/opt/alirezabot/config.php';$v=json_decode(stream_get_contents(STDIN),true);$q=$pdo->prepare('SELECT username FROM admin WHERE id_admin=? AND rule=?');$q->execute([$adminnumber,'administrator']);$name=$q->fetchColumn();if(!$name){exit(2);}$q=$pdo->prepare('UPDATE admin SET password=? WHERE id_admin=?');$q->execute([password_hash($v['password'],PASSWORD_DEFAULT),$adminnumber]);echo json_encode(['username'=>$name]);"""
    result=json.loads(run(['php','-r',script],json.dumps({'password':password})))
    (pathlib.Path(os.environ.get('ALIREZA_ROOT','/var/lib/alirezaserver'))/'bot-job-result.json').unlink(missing_ok=True)
    # PHP session files only: preserve Telegram offsets, inbox and appearance data.
    for session in STATE.glob('sess_*'):
        if session.is_file() and not session.is_symlink():session.unlink()
    return {**result,'password':password,'sessionsRevoked':True}

def sync_local(v):
    if not(APP/'.alirezaserver-managed').exists():raise RuntimeError('BOT_NOT_MANAGED')
    script="require '/opt/alirezabot/config.php';require '/opt/alirezabot/panels/Api/alireza_local.php';$v=json_decode(stream_get_contents(STDIN),true);alireza_sync_local($pdo,$v);"
    run(['php','-r',script],json.dumps({'url':v['bridgeURL'],'token':v['bridgeToken'],'sub':v['subscriptionURL'],'inbounds':v.get('inboundIds',[])}))
    domain=v.get('botDomain') or v.get('domain')
    if domain:
        target=APP/'local-domain.php'
        target.write_text('<?php $domainhosts='+phpvalue(domain)+';\n')
        os.chmod(target,0o640);shutil.chown(target,user='alirezabot',group='alirezabot')
        config=APP/'config.php';source=config.read_text()
        if "require __DIR__.'/local-domain.php'" not in source:
            config.write_text(source+"\nif(is_file(__DIR__.'/local-domain.php')) require __DIR__.'/local-domain.php';\n")
    return {'synchronized':True}

def main(v):
    op=v.get('operation')
    if op=='status':return status()
    if op=='repair-schema':
        from bot_schema import repair_schema
        return repair_schema(APP,STATE,already_locked=True)
    if op=='upgrade-ui':return upgrade_ui()
    if op=='repair-web':return repair_web()
    if op=='reset-password':return reset_password(v)
    if op=='install':
        global_lock=pathlib.Path('/var/lib/alirezaserver/.mirza-install.lock')
        global_lock.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
        with global_lock.open('a') as shared:
            fcntl.flock(shared,fcntl.LOCK_EX)
            return install(v)
    if op=='sync-local':return sync_local(v)
    if op=='retry-failed':return json.loads(run(['runuser','-u','alirezabot','--','php',str(APP/'poll.php'),'--retry-failed'],timeout=660))
    if op in ['start','stop','restart']:
        run(['systemctl',op,*UNITS],timeout=30)
        if op=='stop':run(['systemctl','stop','alirezabot-maintenance.service'],timeout=30)
        return status()
    if op=='uninstall':
        run(['systemctl','disable','--now',*UNITS],timeout=30)
        run(['systemctl','stop','alirezabot-maintenance.service'],timeout=30)
        for u in UNITS+['alirezabot-maintenance.service']:pathlib.Path('/etc/systemd/system',u).unlink(missing_ok=True)
        run(['systemctl','daemon-reload']);return {'retained':'Application, configuration and database retained.','running':False}
    raise RuntimeError('INVALID_OPERATION')
if __name__=='__main__':
    try:
        v=json.load(sys.stdin);lock=None
        if v.get('operation')!='status':
            STATE.mkdir(parents=True,exist_ok=True,mode=0o750);lock=(STATE/'.operation.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        print(json.dumps(main(v)))
    except Exception as e:print(json.dumps({'error':str(e) if isinstance(e,RuntimeError) else type(e).__name__}));sys.exit(1)
