  try:ip=ipaddress.ip_address(v.get(k,''))
  except ValueError:raise RuntimeError('INVALID_'+k)
  if ip.version!=4 or ip.is_loopback or ip.is_multicast or ip.is_unspecified:raise RuntimeError('IPV4_REQUIRED_'+k)
 if v['localPub']==v['remotePub']:raise RuntimeError('TUNNEL_ENDPOINTS_MUST_DIFFER')
 allowed=['tcp','kcp','quic','websocket','wss'] if engine=='gre' else ['tcp','tcpmux','ws','wss','wsmux','wssmux']
 if transport not in allowed or not (carrier in ['direct','auto'] or re.fullmatch(r'(fou|wss):([1-9][0-9]{0,4})',carrier)):raise RuntimeError('INVALID_TRANSPORT_OR_CARRIER')
 port=int(v.get('port',3080));ports=sorted(set(int(str(p).strip()) for p in (v.get('ports',[]) if isinstance(v.get('ports'),list) else str(v.get('ports','')).split(',')) if str(p).strip()))
 if not 1<=port<65535 or not ports or any(p<1 or p>65535 for p in ports):raise RuntimeError('INVALID_PORTS')
