 if hashlib.sha256(src.encode()).hexdigest()!=manifest['hashem']['sha256']:raise RuntimeError('HASHEM_SOURCE_CHECKSUM')
 replacements={'/usr/local/bin':str(APP/'bin'),'/etc/frp':str(CFG/'frp'),'/etc/backhaul':str(CFG/'backhaul'),'/etc/gre-panel':str(CFG/'state'),'/var/lib/gre-panel':str(ROOT/'state'),'/var/backups/hashem':str(ROOT/'backups'),'/var/log/hashem':str(ROOT/'logs'),'19998':'29998','19999':'29999','${HASHEM_SYSTEMD_DIR:-/etc/systemd/system}/':'${HASHEM_SYSTEMD_DIR:-/etc/systemd/system}/alireza-hashem-','/etc/systemd/system/':'/etc/systemd/system/alireza-hashem-','gre-tunnel':'az-hashem-gre','10.10.10.1':'10.251.251.1','10.10.10.2':'10.251.251.2'}
 for a,b in replacements.items():src=src.replace(a,b)
