}
# Never rewrite UFW policy or retire a separate Hashem installation.
ufw(){ return 0; }
carrier_init_kernel(){
 modprobe ip_gre >/dev/null 2>&1 || true
 local mode="${TARGET:-$(carrier_get_active)}" p ports=()
 [[ "$(carrier_get_mode)" != auto ]] || mode=auto
 case "$mode" in direct) return 0;; fou:*) ports=("${mode#fou:}");; wss:*) ports=(29998);; auto) ports=(443 55555 29998);; *) return 1;; esac
 modprobe fou >/dev/null 2>&1 || return 1
 mkdir -p "$PANEL_CONFIG_DIR"
 for p in "${ports[@]}"; do
  if ! ip fou show 2>/dev/null | grep -Eq "^port $p([[:space:]]|$)"; then
   ip fou add port "$p" ipproto 47 || return 1
   : > "$PANEL_CONFIG_DIR/.owned-fou-$p"
  elif [[ ! -f "$PANEL_CONFIG_DIR/.owned-fou-$p" ]]; then
   echo 'Foreign FoU port conflict' >&2; return 1
  fi
  iptables -C INPUT -p udp --dport "$p" -j ACCEPT >/dev/null 2>&1 || iptables -I INPUT 1 -p udp --dport "$p" -j ACCEPT
 done
}
purge_legacy_obfuscation(){ return 0; }
iptables(){
 local a op="" chain="" args=("$@") scoped=()
 for a in "$@"; do case "$a" in -A|-I|-C|-D) op="$a";; INPUT|OUTPUT|POSTROUTING) chain="$a";; esac; done
 [[ -n "$op" && -n "$chain" ]] || return 0
 # Only our tagged rules can be queried/deleted. MSS never applies globally.
 scoped=("${args[@]}" -m comment --comment alirezaserver-hashem)
 [[ "$chain" != POSTROUTING ]] || scoped+=(-o "$TUNNEL_NAME")
 command iptables "${scoped[@]}"
}
install_panel(){ return 0; }
install_panel_smart(){ return 0; }
tune_apply(){ return 0; }

get_latest_frp_version(){ FRP_VERSION=0.71.0; }
install_frp_binaries(){ test -x "${INSTALL_DIR}/frps" && test -x "${INSTALL_DIR}/frpc"; }
install_backhaul_binaries(){ test -x "${INSTALL_DIR}/backhaul"; }
'''
 marker='if [[ $# -gt 0 ]]; then\n    case "$1" in'
 if src.count(marker)!=1:raise RuntimeError('HASHEM_CLI_CONTRACT_CHANGED')
 src=src.replace('sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1','true # No global IP forwarding change; FRP/Backhaul use local sockets')
 src=src.replace('TOKEN="$2"; shift 2', 'TOKEN="${ALIREZA_HASHEM_TOKEN:-$2}"; shift 2')
 src=src.replace('local SPECIFIC_IF="${2:-}"','local SPECIFIC_IF="$TUNNEL_NAME"')
 return src.replace(marker,overrides+'\n'+marker)

def guard():
