 if CFG.exists():shutil.copytree(CFG,dest/'config')
 for name in UNIT_FILES:
  p=SYSTEMD/name
  if p.exists() and p.read_text().startswith(MARKER):shutil.copy2(p,dest/p.name)
 (dest/'timer-active.json').write_text(json.dumps({n:subprocess.run(['systemctl','is-active',n],capture_output=True,text=True,timeout=5).stdout.strip() for n in UNIT_FILES if n.endswith('.timer') and (SYSTEMD/n).exists()}))
 if (ROOT/'last-config.json').exists():shutil.copy2(ROOT/'last-config.json',dest/'last-config.json')
 (dest/'enabled.json').write_text(json.dumps({n:subprocess.run(['systemctl','is-enabled',n],capture_output=True,text=True,timeout=5).stdout.strip() for n in UNIT_FILES if (SYSTEMD/n).exists()}))
 (dest/'firewall.json').write_text(json.dumps(firewall_rules()))
 (dest/'active.json').write_text(json.dumps(status()['services']))
 for old in sorted(p for p in (ROOT/'snapshots').iterdir() if p.is_dir() and not p.is_symlink() and re.fullmatch(r'\d{10,30}',p.name))[:-10]:shutil.rmtree(old)
 return dest
def cleanup_fou(keep=None):
