// SPDX-License-Identifier: GPL-3.0-or-later
import {spawn} from 'node:child_process';import {readFileSync,writeFileSync,renameSync,mkdirSync} from 'node:fs';import {randomBytes} from 'node:crypto';import {fileURLToPath} from 'node:url';
const root=process.env.ALIREZA_ROOT||'/var/lib/alirezaserver',file=root+'/hashem-jobs.json';let active=false;let statusPending,statusCache,statusTime=0;
const fail=(code,status=400)=>Object.assign(Error(code),{code,status});
let jobs=[];try{jobs=JSON.parse(readFileSync(file));for(const j of jobs)if(j.status==='running'){j.status='interrupted';j.error='Panel restarted. Inspect service status before retrying.';}}catch(e){jobs=[];if(e.code!=='ENOENT')console.error('Hashem job metadata is unavailable; inspect the restricted state file.');}
function save(){mkdirSync(root,{recursive:true,mode:0o700});writeFileSync(file+'.tmp',JSON.stringify(jobs.slice(0,20)),{mode:0o600});renameSync(file+'.tmp',file);}
export function execute(operation,input={}){return new Promise((resolve,reject)=>{const p=spawn('python3',[fileURLToPath(new URL(['probe','setup-ssh','peer-ports'].includes(operation)?'./hashem-ssh.py':'./hashem-manager.py',import.meta.url))],{stdio:['pipe','pipe','pipe']});let out='';const timer=setTimeout(()=>{p.kill('SIGTERM');reject(fail('HASHEM_OPERATION_TIMEOUT',504));},1200000);p.stdout.on('data',b=>{out+=b;if(out.length>131072)p.kill();});p.stderr.resume();p.on('error',()=>{clearTimeout(timer);reject(fail('HASHEM_PROCESS_UNAVAILABLE',503));});p.on('close',code=>{clearTimeout(timer);try{const r=JSON.parse(out);if(code||r.error)reject(fail(r.error||'HASHEM_OPERATION_FAILED',502));else resolve(r);}catch{reject(fail('HASHEM_OPERATION_FAILED',502));}});p.stdin.end(JSON.stringify({...input,operation}));});}
