// Transactional client-only profile updates. No user, inbound listener or daemon changes.
import{DatabaseSync}from'node:sqlite';import{pathToFileURL}from'node:url';
const error=(message,status=400)=>Object.assign(Error(message),{status});
let contracts;
async function normalize(){contracts||=import(pathToFileURL((process.env.ALIREZA_NOVA_DIR||'/opt/nova-node-agent')+'/src/xray/inbounds.mjs'));return(await contracts).normalizeProfile;}
function database(){const db=new DatabaseSync(process.env.NOVA_DB||'/var/lib/nova/nova.db');db.exec('PRAGMA busy_timeout=5000');return db;}
const key='network-settings.json';
export async function list(){const norm=await normalize(),db=database();try{let net;try{net=JSON.parse(db.prepare('SELECT v FROM kvstore WHERE k=?').get(key)?.v||'{}');}catch{throw error('HOST_NATIVE_SETTINGS_INVALID');}return{inbounds:(net.inbounds||[]).map(i=>({id:i.id,remark:i.remark,port:i.port,protocol:i.protocol,network:i.network,nodeId:i.nodeId||'local',profiles:(i.profiles||[]).map(norm)}))};}finally{db.close();}}
export async function update(v){const updates=v.updates||[v];if(!Array.isArray(updates)||!updates.length)throw error('HOST_INVALID_UPDATE');const norm=await normalize(),ids=new Set();for(const entry of updates){if(typeof entry.inboundId!=='string'||ids.has(entry.inboundId)||!Array.isArray(entry.profiles)||entry.profiles.length>64||typeof entry.expected!=='string')throw error('HOST_INVALID_UPDATE');ids.add(entry.inboundId);entry.profiles=entry.profiles.map(p=>norm(p));if(entry.profiles.some(p=>!p||(!p.name&&!p.address)))throw error('HOST_NAME_OR_ADDRESS_REQUIRED');}const db=database();try{db.exec('BEGIN IMMEDIATE');const raw=db.prepare('SELECT v FROM kvstore WHERE k=?').get(key)?.v;if(!raw)throw error('HOST_SETTINGS_NOT_FOUND',404);let net;try{net=JSON.parse(raw);}catch{throw error('HOST_NATIVE_SETTINGS_INVALID');}for(const entry of updates){const inbound=(net.inbounds||[]).find(i=>i.id===entry.inboundId);if(!inbound)throw error('HOST_INBOUND_NOT_FOUND',404);if(JSON.stringify((inbound.profiles||[]).map(norm))!==entry.expected)throw error('HOST_CONCURRENT_EDIT_REFRESH',409);for(const p of entry.profiles){if(p.security==='reality'&&(inbound.security||inbound.raw?.streamSettings?.security)!=='reality')throw error('HOST_REALITY_REQUIRES_REALITY_INBOUND');if(inbound.protocol==='shadowsocks'&&p.security&&!['same','none'].includes(p.security))throw error('HOST_SHADOWSOCKS_TLS_OVERRIDE_UNSUPPORTED');if(inbound.protocol==='hysteria2'&&(p.security==='none'||p.finalMask||p.muxParams||p.sockoptParams||p.echConfigList))throw error('HOST_HYSTERIA2_OPTION_UNSUPPORTED');}inbound.profiles=entry.profiles;}db.prepare('UPDATE kvstore SET v=?,updated=? WHERE k=?').run(JSON.stringify(net),Date.now(),key);db.exec('COMMIT');return{ok:true,changedInbounds:updates.length,listenerUnchanged:true};}catch(e){try{db.exec('ROLLBACK');}catch{}throw e;}finally{db.close();}}
