 for(const [name,geo] of [['compat-on',true],['compat-off',false]]){const result=await bridge.request('/panel/api/clients/add','POST',{client:{email:name,geoExits:geo},inboundIds:[]});assert.equal(result.success,true);assert.ok(result.obj.configs.length);const user=(await native.getSettings(kv)).users.find(u=>u.name===name);assert.equal(user.geoExits,geo);const link=new URL(result.obj.configs[0]);assert.equal(link.hostname,'8.8.8.8');assert.equal(link.searchParams.get('security'),'tls');assert.equal(link.searchParams.get('type'),'ws');const cfg=JSON.parse(fs.readFileSync(root+'/xray/config.json'));assert.ok(cfg.inbounds.some(i=>i.settings?.clients?.some(c=>c.id===user.uuid)));}
