form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const v=Object.fromEntries(new FormData(form));v.quotaBytes=Number(v.quotaGB||form.elements.minGB.value||1)*1073741824;v.geoExits=form.elements.geoExits.checked;v.active=form.elements.active.checked;v.inboundIds=[...document.querySelectorAll('#inbounds input:checked')].map(x=>x.value);v.caps=[...document.querySelectorAll('#caps input:checked')].map(x=>x.value);if(!v.id)delete v.id;await api('save-plan',v);$('#editor').close();await refresh();}catch(e){notice(e.message);}finally{busy=false;}};$('#botform').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{await api('configure',{token:$('#token').value,enabled:$('#enabled').checked,adminChat:$('#adminChat').value,paymentInstructions:$('#instructions').value});$('#token').value='';await refresh();}catch(e){notice(e.message);}finally{busy=false;}};$('#deleteToken').onclick=async()=>{if(confirm(tr('توکن حذف و ربات متوقف شود؟','Delete token and stop bot?'))){try{await api('configure',{deleteToken:true});await refresh();}catch(e){notice(e.message);}}};(async()=>{translate();try{catalog=await api('catalog');$('#roles').innerHTML=catalog.roles.map(r=>`<option>${esc(r)}</option>`).join('');if(catalog.who.role!=='owner')form.elements.kind.querySelector('[value="admin"]').remove();$('#inbounds').innerHTML=catalog.inbounds.map(i=>`<label class="check"><input type="checkbox" value="${esc(i.id)}"> ${esc(i.remark||i.id)} · ${esc(i.protocol)} · ${esc(i.port)}</label>`).join('');$('#caps').innerHTML=catalog.caps.map(c=>`<label class="check"><input type="checkbox" value="${esc(c)}"> ${esc(c)}</label>`).join('');await refresh();}catch(e){notice(e.message);}})();})();
