export async function purchase(owner,buyer,qid,native,{externalPaid=false,panelURL}={}){buyer=buyerId(buyer);const identity=await native('/admin/whoami');if(owner!=='owner'&&(String(identity.id)!==owner||!identity.caps?.includes('users.create')))throw err('SHOP_IDENTITY_MISMATCH',403);let row=database().prepare('SELECT * FROM orders WHERE id=? AND owner=? AND buyer=?').get(String(qid),owner,buyer);if(!row){const q=getQuote(owner,buyer,qid);if(owner!=='owner'&&identity.selling?.mode==='volume'&&((identity.selling.remainingBytes!==undefined&&q.plan.quotaBytes>identity.selling.remainingBytes)||(identity.selling.remainingUsers!==undefined&&identity.selling.remainingUsers<=0)))throw err('SHOP_NATIVE_QUOTA_LOW',409);if(Date.now()-q.created>900000)throw err('SHOP_QUOTE_EXPIRED');await validateGrant(q.plan);const password=randomBytes(24).toString('base64url'),data={plan:q.plan,name:'shop-'+q.id.slice(0,20),password:seal({password},'shop-password'),externalPaid};tx(d=>{if(d.prepare('SELECT id FROM orders WHERE id=?').get(q.id))return;if(!externalPaid){const n=d.prepare('UPDATE wallets SET balance=balance-? WHERE owner=? AND buyer=? AND balance>=?').run(q.plan.price,owner,buyer,q.plan.price);if(!n.changes&&q.plan.price!==0)throw err('SHOP_INSUFFICIENT_BALANCE',409);}d.prepare("INSERT INTO orders(id,owner,buyer,data,status,created) VALUES(?,?,?,?,'reserved',?)").run(q.id,owner,buyer,JSON.stringify(data),Date.now());});}
 row=database().prepare('SELECT * FROM orders WHERE id=? AND owner=? AND buyer=?').get(String(qid),owner,buyer);if(row.status==='cancelled')throw err('SHOP_ORDER_CANCELLED',409);if(row.status==='awaiting_payment'){if(!externalPaid)throw err('SHOP_PAYMENT_REQUIRED',409);database().prepare("UPDATE orders SET status='reserved' WHERE id=? AND owner=? AND status='awaiting_payment'").run(qid,owner);}if(row.status==='ready')return order(owner,buyer,qid,{credentials:true});if(row.lease>Date.now())return order(owner,buyer,qid);const lease=Date.now()+120000;const claim=database().prepare("UPDATE orders SET lease=?,status='provisioning' WHERE id=? AND owner=? AND lease<=? AND status!='ready'").run(lease,qid,owner,Date.now());if(!claim.changes)return order(owner,buyer,qid);const data=json(row),p=data.plan,password=unseal(data.password,'shop-password').password;try{let result;if(p.kind==='admin'){if(owner!=='owner')throw err('SHOP_ADMIN_SALE_OWNER_ONLY',403);const list=await native('/admin/admins');const existing=list.admins?.find(a=>a.name===data.name);if(!existing)await native('/admin/admins','POST',{name:data.name,password,role:p.role,caps:p.caps,...(p.role==='reseller'?{mode:'volume',quotaBytes:p.quotaBytes,maxUsers:p.maxUsers,custExpireDays:p.days,inboundIds:p.inboundIds,allowGeo:p.geoExits}:{}),...(p.role==='admin1'?{ownerPassword:await validateGrant(p)}:{}),note:'Alirezabot order '+qid});const current=(await native('/admin/admins')).admins?.find(a=>a.name===data.name);if(!current)throw err('SHOP_ADMIN_NOT_CONFIRMED',502);result={username:data.name,password,panelURL,adminId:current.id};}else{const settings=await native(owner==='owner'?'/admin/network-settings.json':'/admin/users.json');let user=(settings.users||[]).find(u=>u.name===data.name);if(!user){user={id:'shop-'+qid,uuid:randomUUID(),name:data.name,email:data.name,enabled:true,quotaBytes:p.quotaBytes,expiry:new Date(Date.now()+p.days*86400000).toISOString(),inboundIds:p.inboundIds,geoExits:p.geoExits,note:'Alirezabo