// SPDX-License-Identifier: GPL-3.0-or-later
// Customer management is bound to the paid order AND Telegram buyer identity.
import{randomBytes}from'node:crypto';import * as shop from'./shop.mjs';import{seal,unseal}from'./vault.mjs';
const locks=new Map(),fail=(m,s=400)=>Object.assign(Error(m),{status:s,code:m});
const buyerId=v=>{if(!/^[1-9][0-9]{0,19}$/.test(String(v)))throw fail('PANEL_INVALID_BUYER');return String(v);};
function paid(buyer,id){buyer=buyerId(buyer);const row=shop.database().prepare("SELECT * FROM orders WHERE owner='owner' AND buyer=? AND id=? AND status='ready'").get(buyer,String(id));if(!row||JSON.parse(row.data).plan.kind!=='admin')throw fail('PANEL_NOT_FOUND',404);const c=unseal(JSON.parse(row.credentials),'shop-order');return{row,c};}
export function list(buyer,offset=0){buyer=buyerId(buyer);if(!Number.isSafeInteger(offset)||offset<0)throw fail('PANEL_INVALID_PAGE');return shop.database().prepare("SELECT id,data FROM orders WHERE owner='owner' AND buyer=? AND status='ready' AND json_extract(data,'$.plan.kind')='admin' ORDER BY created DESC LIMIT 11 OFFSET ?").all(buyer,offset).map(r=>({id:r.id,name:JSON.parse(r.data).plan.name}));}
export async function info(buyer,id,ctx,{credentials=false}={}){const{c}=paid(buyer,id),native=ctx.native('owner');const a=(await native('/admin/admins')).admins.find(a=>a.id===c.adminId);if(!a||a.enabled===false)throw fail('PANEL_DISABLED_OR_REMOVED',409);const who=await ctx.native(c.adminId)('/admin/whoami');if(who.id!==c.adminId)throw fail('PANEL_IDENTITY_MISMATCH',403);return{id,username:c.username,panelUrl:await ctx.panelURL(),role:a.role,quotaBytes:a.quotaBytes??null,remainingBytes:who.selling?.remainingBytes??null,maxUsers:a.maxUsers??null,remainingUsers:who.selling?.remainingUsers??null,...(credentials?{password:c.password}:{}),passwordNotice:'Stored delivery password; use reset if changed elsewhere.'};}
export async function rotate(buyer,id,ctx){buyer=buyerId(buyer);const key=buyer+':'+id;if(locks.has(key))return locks.get(key);const work=(async()=>{let{row,c}=paid(buyer,id);await info(buyer,id,ctx);const data=JSON.parse(row.data);if(!data.pendingRotation&&Date.now()-(data.rotationAt||0)<60000)throw fail('PANEL_PASSWORD_WAIT_ONE_MINUTE',429);const pending=data.pendingRotation?unseal(data.pendingRotation,'panel-rotation').password:randomBytes(24).toString('base64url');if(!data.pendingRotation){data.pendingRotation=seal({password:pending},'panel-rotation');shop.database().prepare("UPDATE orders SET data=? WHERE id=? AND buyer=? AND owner='owner'").run(JSON.stringify(data),id,buyer);}
 await ctx.native('owner')('/admin/admins','POST',{action:'password',id:c.adminId,password:pending});c={...c,password:pending};delete data.pendingRotation;data.rotationAt=Date.now();shop.database().prepare("UPDATE orders SET credentials=?,data=? WHERE id=? AND buyer=? AND owner='owner'").run(JSON.stringify(seal(c,'shop-order')),JSON.stringify(data),id,buyer);return{ok:true,password:pending,panelUrl:await ctx.panelURL(),username:c.username};})();locks.set(key,work);try{return await work;}finally{locks.delete(key);}}
