import json,pathlib
p=pathlib.Path('/var/lib/alirezaserver/nova-source.json')
if not p.exists():
    import hashlib,os
    agent=pathlib.Path('/opt/nova-node-agent');v=json.loads((agent/'package.json').read_text())['version']
    profiles=json.loads(pathlib.Path('/opt/alirezaserver/compat-profiles.json').read_text())['profiles']
    for item in profiles:
        if item['version']==v and all(hashlib.sha256((agent/name).read_bytes()).hexdigest()==digest for name,digest in item['files'].items()):
            p.write_text(json.dumps({key:item[key] for key in ['version','commit','sha256']}));os.chmod(p,0o600);break
